import Foundation
import Supabase

extension SupabaseClient {
    static let shared: SupabaseClient = {
        let raw = Bundle.main.infoDictionary
        let rawURL = raw?["SUPABASE_URL"] as? String ?? ""
        let rawKey = raw?["SUPABASE_ANON_KEY"] as? String ?? ""

        // Valid when xcconfig is applied (non-empty, not unexpanded build-setting reference)
        let isConfigured = !rawURL.isEmpty && !rawURL.hasPrefix("$(")
                        && !rawKey.isEmpty && !rawKey.hasPrefix("$(")

        if isConfigured, let url = URL(string: rawURL) {
            // 기본 KeychainLocalStorage 대신 ResilientAuthStorage 주입 — 미서명 시뮬 빌드에서
            // Keychain 영속 실패 시 세션이 조용히 유실돼 RPC가 role=anon(42501)이 되던 버그 차단.
            return SupabaseClient(
                supabaseURL: url,
                supabaseKey: rawKey,
                options: SupabaseClientOptions(
                    auth: SupabaseClientOptions.AuthOptions(storage: ResilientAuthStorage())
                )
            )
        }

        // Not configured — crash in production, stub in test environment
        let isTest = NSClassFromString("XCTestCase") != nil
                  || ProcessInfo.processInfo.environment["XCTestSessionIdentifier"] != nil
                  || ProcessInfo.processInfo.environment["XCInjectBundleInto"] != nil
        guard isTest else {
            fatalError("SUPABASE_URL / SUPABASE_ANON_KEY not found in Info.plist — check Secrets.xcconfig")
        }
        return SupabaseClient(
            supabaseURL: URL(string: "https://placeholder.supabase.co")!,
            supabaseKey: "placeholder-anon-key"
        )
    }()
}

