.pm{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:10px}
.tile{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:12px 14px}
.tile .n{font-size:26px;font-weight:900;font-variant-numeric:tabular-nums;line-height:1.1}
.tile .k{font-size:12px;color:var(--sub);margin-top:2px}
.tile.live .n{color:var(--live)} .tile.warn .n{color:var(--warn)} .tile.bad .n{color:var(--bad)}
.defrow{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}
.defchip{display:inline-flex;align-items:center;gap:7px;border:1px solid var(--line);
