.fcard{position:relative;background:var(--card);border:1px solid var(--line);border-radius:11px;
  padding:13px 15px 12px 18px;cursor:pointer;text-align:left;color:var(--ink);font:inherit;
  transition:border-color .12s, transform .12s}
.fcard::before{content:"";position:absolute;left:0;top:10px;bottom:10px;width:4px;border-radius:0 4px 4px 0}
.fcard.s-LIVE::before{background:var(--live)}
.fcard.s-REFACTOR_IN_PROGRESS::before{background:var(--warn)}
.fcard.s-PLANNED::before,.fcard.s-SWITCHED_OVER::before{background:var(--sub)}
.fcard:hover{border-color:var(--accent)}
.fcard:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.fcard.hl{border-color:var(--bad);box-shadow:0 0 0 3px var(--bad-soft)}
@media (prefers-reduced-motion: no-preference){ .fcard:hover{transform:translateY(-1px)} }
.fcard .ft{font-weight:800;font-size:14.5px;display:flex;justify-content:space-between;gap:8px;align-items:baseline}
.fcard .fid{font-size:10.5px;color:var(--sub)}
.fcard .route{margin-top:7px;background:var(--mono-bg);border-radius:6px;padding:4px 8px;
  font-size:11.5px;overflow-x:auto;white-space:nowrap}
.meta{display:flex;justify-content:space-between;align-items:center;margin-top:9px}
.plats{display:flex;gap:5px}
.pd{font-size:10px;font-weight:800;border-radius:5px;padding:2.5px 6px;letter-spacing:.02em}
.pd.on{background:var(--accent-soft);color:var(--accent)}
.pd.off{background:transparent;color:var(--sub);border:1px dashed var(--line);opacity:.65}
.badges{display:flex;gap:5px}
.stat{font-size:10.5px;font-weight:800;border-radius:999px;padding:2px 8px}
.stat.LIVE{background:var(--live-soft);color:var(--live)}
.stat.REFACTOR_IN_PROGRESS{background:var(--warn-soft);color:var(--warn)}
.stat.PLANNED,.stat.SWITCHED_OVER{background:var(--mono-bg);color:var(--sub)}
.dcount{font-size:10.5px;font-weight:800;border-radius:999px;padding:2px 8px;background:var(--bad-soft);color:var(--bad)}
/* drawer */
.scrim{position:fixed;inset:0;background:rgba(15,16,24,.42);opacity:0;pointer-events:none;transition:opacity .18s}
.scrim.open{opacity:1;pointer-events:auto}
.drawer{position:fixed;top:0;right:0;bottom:0;width:min(480px,94vw);background:var(--drawer);
