.drawer.open{transform:none}
@media (prefers-reduced-motion: reduce){ .drawer,.scrim{transition:none} }
.drawer h3{margin:0;font-size:19px;font-weight:900}
.drawer .sub{color:var(--sub);font-size:12.5px;margin-top:2px}
.drawer .close{position:absolute;top:16px;right:16px;border:1px solid var(--line);background:var(--card);
  color:var(--ink);border-radius:8px;width:32px;height:32px;font-size:15px;cursor:pointer}
.drawer .close:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.sec{margin-top:20px}
