<script>
const DATA = __ATLAS_DATA__;
const feats = DATA.features, defects = DATA.defects;
const defByFeat = {};
defects.forEach(d => { (defByFeat[d.relatedFeature] ||= []).push(d); });
const CAP_ORDER = ["CAP-GROUP","CAP-SCHEDULE","CAP-PLACE-CONFIRM"];
const STATUS_KO = {LIVE:"LIVE", REFACTOR_IN_PROGRESS:"진행", PLANNED:"계획", SWITCHED_OVER:"전환"};

/* 계층 1 — PM 개요 */
const live = feats.filter(f=>f.status==="LIVE").length;
const prog = feats.filter(f=>f.status==="REFACTOR_IN_PROGRESS").length;
const p1 = defects.filter(d=>d.severity==="P1").length;
const androidOn = feats.filter(f=>f.implementedBy && f.implementedBy.android).length;
document.getElementById("pm").innerHTML = `
  <div class="tile"><div class="n">${feats.length}</div><div class="k">feature</div></div>
  <div class="tile live"><div class="n">${live}</div><div class="k">LIVE — E2E 재현 확인</div></div>
  <div class="tile warn"><div class="n">${prog}</div><div class="k">진행 중</div></div>
  <div class="tile bad"><div class="n">${p1}<span style="font-size:14px;color:var(--sub)"> / ${defects.length}</span></div><div class="k">P1 결함 / 전체</div></div>
  <div class="tile"><div class="n">${androidOn}<span style="font-size:14px;color:var(--sub)"> / ${feats.length}</span></div><div class="k">Android 배선</div></div>`;
document.getElementById("defrow").innerHTML = defects.map(d =>
  `<button class="defchip" data-feat="${d.relatedFeature}">
     <span class="sev ${d.severity}">${d.severity}</span>${d.id} · ${d.title}</button>`).join("");

/* 계층 2 — capability → feature 카드 */
const capsEl = document.getElementById("caps");
CAP_ORDER.forEach(cid => {
  const group = feats.filter(f=>f.capabilityId===cid);
  if (!group.length) return;
  const sec = document.createElement("section");
  sec.className = "cap";
  sec.innerHTML = `<h2>${group[0].capabilityTitle} <span class="capid mono">${cid}</span></h2>
    <div class="grid">` + group.map(f => {
      const im = f.implementedBy || {};
      const plats = ["ios","android","edge","sql"].map(p =>
        `<span class="pd ${im[p] ? "on":"off"}">${p.toUpperCase()}</span>`).join("");
      const dn = (defByFeat[f.featureId]||[]).length;
      return `<button class="fcard s-${f.status}" data-ft="${f.featureId}" id="card-${f.featureId}">
        <div class="ft"><span>${f.title}</span><span class="fid mono">${f.featureId}</span></div>
        <div class="route mono">${(f.owns||[]).map(o=>o.route).join(" · ")}</div>
        <div class="meta"><div class="plats">${plats}</div>
          <div class="badges">${dn?`<span class="dcount">결함 ${dn}</span>`:""}
          <span class="stat ${f.status}">${STATUS_KO[f.status]||f.status}</span></div></div>
      </button>`;
    }).join("") + `</div>`;
  capsEl.appendChild(sec);
});

/* 계층 3 — Dev 상세 드로어 */
const drawer = document.getElementById("drawer"), scrim = document.getElementById("scrim");
function openFeat(fid){
  const f = feats.find(x=>x.featureId===fid); if(!f) return;
  const im = f.implementedBy || {};
  const kv = ["ios","android","edge","sql"].map(p => im[p]
    ? `<div class="k">${p}</div><div class="v mono">${im[p]}</div>`
    : `<div class="k">${p}</div><div class="v none">없음${p==="android"?" — 진입 배선 전":""}</div>`).join("");
  const ops = (f.owns||[]).map(o => `
    <div class="oprow"><div class="r mono">${o.route}</div>
      <div class="tags">
        <span class="tag">${o.operationId}</span><span class="tag">auth ${o.auth}</span>
        <span class="tag ${o.safety.sideEffect==="READ"?"ok":"w"}">${o.safety.sideEffect}</span>
        ${o.safety.writes.length?`<span class="tag w">writes: ${o.safety.writes.join(", ")}</span>`:""}
        <span class="tag ${o.safety.rerunSafe?"ok":"w"}">rerun ${o.safety.rerunSafe?"안전":"불가"}</span>
        <span class="tag">${o.safety.abortOnFail}</span>
      </div></div>`).join("");
  const ds = (defByFeat[fid]||[]).map(d => `
    <div class="dfull"><div class="t"><span class="sev ${d.severity}">${d.severity}</span>${d.id} · ${d.title}</div>
      <div class="d">${d.detail||""}</div>
      ${d.evidence?`<div class="ev mono">${d.evidence.path}${d.evidence.line?":"+d.evidence.line:""}${d.evidence.symbol?" · "+d.evidence.symbol:""}</div>`:""}
    </div>`).join("");
  drawer.innerHTML = `
    <button class="close" aria-label="닫기">✕</button>
    <h3>${f.title}</h3>
    <div class="sub mono">${f.featureId} · ${f.capabilityId} · <span class="stat ${f.status}">${STATUS_KO[f.status]||f.status}</span></div>
    <div class="sec"><div class="h">Operations · Safety</div>${ops}</div>
    <div class="sec"><div class="h">구현 위치</div><div class="kv">${kv}</div></div>
    ${ds?`<div class="sec"><div class="h">알려진 결함</div>${ds}</div>`:""}
    <div class="sec"><div class="h">테스트</div><ul class="tests">${(f.tests||[]).map(t=>`<li class="mono">${t}</li>`).join("")||"<li class='v none'>없음</li>"}</ul></div>`;
  drawer.classList.add("open"); scrim.classList.add("open");
  drawer.querySelector(".close").focus();
}
function closeDrawer(){ drawer.classList.remove("open"); scrim.classList.remove("open"); }
document.addEventListener("click", e => {
  const card = e.target.closest(".fcard");
  if (card) return openFeat(card.dataset.ft);
  const chip = e.target.closest(".defchip");
  if (chip){
    const el = document.getElementById("card-"+chip.dataset.feat);
    if (el){ el.scrollIntoView({behavior:"smooth",block:"center"});
      document.querySelectorAll(".fcard.hl").forEach(x=>x.classList.remove("hl"));
      el.classList.add("hl"); setTimeout(()=>openFeat(chip.dataset.feat), 350); }
    return;
  }
  if (e.target.closest(".close") || e.target===scrim) closeDrawer();
});
document.addEventListener("keydown", e => { if(e.key==="Escape") closeDrawer(); });
</script>
