  ["FT-LOCATION-INPUT","FT-MIDPOINT"],["FT-MIDPOINT","FT-PLACE-HANDOFF"],
  ["FT-PLACE-HANDOFF","FT-CONFIRM"],["FT-CONFIRM","FT-RESULT-SHARE"]];
const COLW = 340, NODEW = 288, ROWH = 158, TOP = 56, LEFT = 26;
const CW = LEFT*2 + PHASES.length*COLW - (COLW-NODEW);
const CH = TOP + Math.max(...PHASES.map(p=>p.nodes.length))*ROWH + 30;
const nmc = document.getElementById("nmcanvas");
nmc.style.width = CW+"px"; nmc.style.height = CH+"px";
const pos = {};
let nmHtml = `<svg class="nmsvg" width="${CW}" height="${CH}" aria-hidden="true"></svg>`;
PHASES.forEach((ph,c)=>{
