    const plats = ["ios","android","edge","sql"].map(k=>`<span class="pd ${im[k]?"on":"off"}">${k.toUpperCase()}</span>`).join("");
    const routes = (f.owns||[]).map(o=>o.route).filter(r=>!r.startsWith("SCREEN"));
    const tn = (f.tests||[]).length, dn = (defByFeat[n.ft]||[]).length;
    nmHtml += `<button class="nmnode${p1}" style="left:${x}px;top:${y}px" data-ft="${n.ft}">
      <span class="seq">${n.seq}</span>
      <div class="eyebrow">${n.user}</div>
      <div class="tt"><span>${f.title||n.ft}</span><span class="fid mono">${n.ft}</span></div>
      ${routes.length?`<div class="rt mono">${routes.join(" · ")}</div>`:""}
      <div class="row"><div class="plats">${plats}</div>
        <div class="chips">${tn?`<span class="chip t">test ${tn}</span>`:""}${dn?`<span class="chip d">결함 ${dn}</span>`:""}
        <span class="stat ${f.status}">${STATUS_KO[f.status]||f.status||""}</span></div></div>
    </button>`;
  });
});
nmc.innerHTML = nmHtml;
const svg = nmc.querySelector(".nmsvg");
svg.innerHTML = JOURNEY_EDGES.map(([a,b])=>{
  const A = pos[a], B = pos[b]; if(!A||!B) return "";
  const x1 = A.x+NODEW, y1 = A.y+62, x2 = B.x, y2 = B.y+62;
  const mid = (x1+x2)/2;
  const bad = (p1Feats.has(a)||p1Feats.has(b)) ? ' class="badedge"' : "";
