function applyView(smooth){
  nmc.classList.toggle("smooth", !!smooth);
  nmc.style.transform = `translate(${view.x}px,${view.y}px) scale(${view.z})`;
  vp.style.setProperty("--gs", view.z);
  vp.style.setProperty("--gx", view.x+"px");
  vp.style.setProperty("--gy", view.y+"px");
}
function fitView(smooth){
  const r = vp.getBoundingClientRect();
  view.z = Math.min(r.width/CW2, r.height/CH2)*0.98;
  view.x = (r.width - CW2*view.z)/2; view.y = (r.height - CH2*view.z)/2;
