let panning=null;
vp.addEventListener("pointerdown", e=>{
  if (e.target.closest(".nmnode")) return;
  panning = {sx:e.clientX, sy:e.clientY, ox:view.x, oy:view.y};
  vp.classList.add("pan"); vp.setPointerCapture(e.pointerId);
});
vp.addEventListener("pointermove", e=>{
  if(!panning) return;
  view.x = panning.ox + (e.clientX-panning.sx);
  view.y = panning.oy + (e.clientY-panning.sy);
  applyView(false);
});
["pointerup","pointercancel"].forEach(ev=>vp.addEventListener(ev, ()=>{ panning=null; vp.classList.remove("pan"); }));
vp.addEventListener("wheel", e=>{
  e.preventDefault();
  const r = vp.getBoundingClientRect();
  const mx = e.clientX-r.left, my = e.clientY-r.top;
  const oldZ = view.z;
  view.z = Math.min(1.6, Math.max(.25, view.z * (e.deltaY<0 ? 1.09 : 0.92)));
  view.x = mx - (mx-view.x)*(view.z/oldZ);
  view.y = my - (my-view.y)*(view.z/oldZ);
  applyView(false);
}, {passive:false});
document.querySelector(".nmzoom").addEventListener("click", e=>{
  const b=e.target.closest("button"); if(!b) return;
  const z=+b.dataset.z;
  if (z===0) return fitView(true);
  const r = vp.getBoundingClientRect();
  const oldZ=view.z;
  view.z = Math.min(1.6, Math.max(.25, view.z + z*0.15));
  view.x = r.width/2 - (r.width/2-view.x)*(view.z/oldZ);
  view.y = r.height/2 - (r.height/2-view.y)*(view.z/oldZ);
  applyView(true);
});
document.getElementById("nmtheme").addEventListener("click", e=>{
  const b=e.target.closest("button"); if(!b) return;
  document.getElementById("nm").dataset.mtheme = b.dataset.t;
  document.querySelectorAll("#nmtheme button").forEach(x=>x.classList.toggle("on", x===b));
});
nmc.addEventListener("click", e=>{ const n=e.target.closest(".nmnode"); if(n) openFeat(n.dataset.ft); });
fitView(false);
addEventListener("resize", ()=>fitView(false));
"""
