    94	            {page.states.map((state) => (
    95	              <button
    96	                key={state.id}
    97	                type="button"
    98	                className={pageState === state.id ? 'is-active' : ''}
    99	                onClick={() => onPageStateChange(state.id)}
   100	                aria-pressed={pageState === state.id}
   101	              >
   102	                {state.label}
   103	              </button>
   104	            ))}
