   134	  cards: readonly AtlasCard[];
   135	}
     1	/**
     2	 * 왼쪽 패널 — 제품 페이지 전체가 한 화면에 들어간다.
     3	 *
     4	 * iframe은 same-origin이라 문서를 직접 잴 수 있고, 제품이 심어둔
     5	 * data-atlas-node 좌표가 postMessage로 넘어와 카드 영역이 그 위에 얹힌다.
     6	 * 측정과 배율은 usePreviewStage가 소유한다 — 여기는 그리기만 한다.
     7	 */
     8	import { Icon } from '@iconify/react';
     9	import { MAX_ZOOM, MEASURE_VIEWPORT_HEIGHT, MIN_ZOOM, PREVIEW_BASE_WIDTH, usePreviewStage } from '../use-preview-stage';
    10	import type { AtlasPageCards } from '@/types/atlas-card';
    11	
    12	interface Props {
    13	  page: AtlasPageCards;
    14	  pageState: string;
    15	  onPageStateChange: (stateId: string) => void;
    16	  // 훅의 반환값을 그대로 받는다. 손으로 다시 적으면 ref의 null 허용 여부처럼
    17	  // 사소한 차이가 갈라져서, 훅을 고칠 때 여기가 조용히 어긋난다.
    18	  stage: ReturnType<typeof usePreviewStage>;
    19	  selectedCardId: string | null;
    20	  highlightId: string | null;
    21	  onSelectCard: (cardId: string) => void;
    22	  onHoverCard: (cardId: string | null) => void;
    23	}
    24	
    25	export function AtlasPagePanel({
    26	  page,
    27	  pageState,
    28	  onPageStateChange,
    29	  stage,
    30	  selectedCardId,
    31	  highlightId,
    32	  onSelectCard,
    33	  onHoverCard,
    34	}: Props) {
    35	  const {
    36	    iframeRef, stageRef, rects, docHeight,
    37	    fitScale, previewScale, isFit,
    38	    changeZoom, fitZoom, reloadPreview, onPreviewLoad,
    39	  } = stage;
    40	
    41	  const activeState = page.states.find((state) => state.id === pageState) ?? page.states[0] ?? null;
    42	  // 상태가 바뀌면 URL이 바뀌고, key가 바뀌면 iframe이 새로 뜬다
    43	  const previewSrc = pageState === 'default'
    44	    ? page.previewSrc
    45	    : `${page.previewSrc}&atlasState=${encodeURIComponent(pageState)}`;
    46	
    47	  return (
    48	    <section className="atlas-page-panel">
    49	      <div className="atlas-page-head">
    50	        <div>
    51	          <span>PAGE VIEW / 전체</span>
    52	          <strong>{page.route}</strong>
    53	        </div>
    54	        <div className="atlas-page-meta">
    55	          <div className="atlas-zoom" role="group" aria-label="미리보기 배율">
    56	            <button
    57	              type="button"
    58	              onClick={() => changeZoom(-1)}
    59	              disabled={!fitScale || previewScale <= MIN_ZOOM}
    60	              title="축소"
    61	              aria-label="축소"
    62	            >
    63	              <Icon icon="solar:minus-square-outline" width={14} />
    64	            </button>
    65	            <span>{previewScale ? `${Math.round(previewScale * 100)}%` : '측정 중'}</span>
    66	            <button
    67	              type="button"
    68	              onClick={() => changeZoom(1)}
    69	              disabled={!fitScale || previewScale >= MAX_ZOOM}
    70	              title="확대"
    71	              aria-label="확대"
    72	            >
    73	              <Icon icon="solar:add-square-outline" width={14} />
    74	            </button>
    75	            <button
    76	              type="button"
    77	              className={isFit ? 'is-active' : ''}
    78	              onClick={fitZoom}
    79	              title="전체 맞춤 — 스크롤 없이 페이지 전체"
    80	              aria-pressed={isFit}
    81	            >
    82	              FIT
    83	            </button>
    84	          </div>
    85	          <button type="button" onClick={reloadPreview} title="미리보기 새로고침">
    86	            <Icon icon="solar:refresh-outline" width={13} />
    87	          </button>
    88	        </div>
    89	      </div>
    90	
    91	      {page.states.length > 0 && (
    92	        <div className="atlas-state-bar">
    93	          <div className="atlas-state-tabs" role="group" aria-label="화면 상태">
    94	            {page.states.map((state) => (
    95	              <button
    96	                key={state.id}
    97	                type="button"
    98	                className={pageState === state.id ? 'is-active' : ''}
    99	                onClick={() => onPageStateChange(state.id)}
   100	                aria-pressed={pageState === state.id}
   101	              >
   102	                {state.label}
   103	              </button>
   104	            ))}
   105	          </div>
   106	          {activeState && (
   107	            <div className="atlas-state-note">
   108	              <p>{activeState.note}</p>
   109	              {activeState.caveat && <p className="is-caveat">{activeState.caveat}</p>}
   110	            </div>
   111	          )}
   112	        </div>
   113	      )}
   114	
   115	      <div className="atlas-page-stage" ref={stageRef} data-fit={isFit ? 'true' : 'false'}>
   116	        {/* 배율이 반영된 실제 크기. transform은 레이아웃 크기를 바꾸지 않으므로
   117	            이 래퍼가 스크롤 영역을 만든다. */}
   118	        <div
   119	          className="atlas-page-canvas"
   120	          style={{
   121	            width: PREVIEW_BASE_WIDTH * (previewScale || 0.01),
   122	            height: (docHeight || MEASURE_VIEWPORT_HEIGHT) * (previewScale || 0.01),
   123	          }}
   124	        >
   125	          <div
   126	            className="atlas-page-scaler"
   127	            style={{
   128	              width: PREVIEW_BASE_WIDTH,
   129	              height: docHeight || undefined,
   130	              transform: `scale(${previewScale || 0.01})`,
   131	            }}
   132	          >
   133	            <iframe
   134	              ref={iframeRef}
   135	              key={`${page.pageId}-${pageState}`}
   136	              title={`${page.title} 전체 미리보기 (${activeState?.label ?? '기본'})`}
   137	              src={previewSrc}
   138	              style={{ width: PREVIEW_BASE_WIDTH, height: docHeight || MEASURE_VIEWPORT_HEIGHT }}
   139	              onLoad={onPreviewLoad}
   140	            />
   141	
   142	            {page.cards.map((card) => {
   143	              const rect = rects[card.id];
   144	              if (!rect) return null;
   145	              return (
   146	                <button
   147	                  type="button"
   148	                  key={card.id}
   149	                  className={`atlas-region ${highlightId === card.id ? 'is-active' : ''} ${selectedCardId === card.id ? 'is-selected' : ''}`}
   150	                  style={{ left: rect.x, top: rect.y, width: rect.width, height: rect.height }}
   151	                  onClick={() => onSelectCard(card.id)}
   152	                  onMouseEnter={() => onHoverCard(card.id)}
   153	                  onMouseLeave={() => onHoverCard(null)}
   154	                  aria-label={`${card.title} 영역`}
   155	                >
   156	                  <span style={{ transform: `scale(${previewScale ? 1 / previewScale : 1})` }}>
   157	                    {card.code}
   158	                  </span>
   159	                </button>
   160	              );
   161	            })}
   162	          </div>
   163	        </div>
   164	
   165	        {!docHeight && (
   166	          <div className="atlas-page-waiting">
   167	            <Icon icon="solar:radar-2-outline" width={20} />
   168	            DOCUMENT MEASURING
   169	          </div>
   170	        )}
   171	      </div>
   172	
   173	      <div className="atlas-page-foot">
   174	        <span><i className="is-green" /> SAME ORIGIN</span>
   175	        <span><i /> NO SCROLL · 전체 {docHeight || '—'}px</span>
   176	      </div>
   177	    </section>
   178	  );
   179	}

