import Foundation
import Supabase

extension SupabaseClient {
    static let shared: SupabaseClient = {
        let raw = Bundle.main.infoDictionary
        let rawURL = raw?["SUPABASE_URL"] as? String ?? ""
        let rawKey = raw?["SUPABASE_ANON_KEY"] as? String ?? ""

        // Valid when xcconfig is applied (non-empty, not unexpanded build-setting reference)
