import XCTest

final class AtlasDumpUITests: XCTestCase {
    private let app = XCUIApplication()

    func testAtlasDump() {
        addUIInterruptionMonitor(withDescription: "위치 권한") { alert in
            let allow = alert.buttons["허용"].firstMatch
            if allow.exists {
                allow.tap()
                return true
            }
            let whileUsing = alert.buttons["앱을 사용하는 동안 허용"].firstMatch
            if whileUsing.exists {
                whileUsing.tap()
                return true
            }
            return false
        }

        app.launch()
        dump(screenName: "group-list")

        let group = app.staticTexts.matching(NSPredicate(format: "label BEGINSWITH 'UITEST'" )).firstMatch
        XCTAssertTrue(group.waitForExistence(timeout: 30))
        group.tap()

        let appointment = app.staticTexts.matching(NSPredicate(format: "label BEGINSWITH 'UITEST'" )).firstMatch
        XCTAssertTrue(appointment.waitForExistence(timeout: 30))
        dump(screenName: "appointment-list")
        appointment.tap()

        XCTAssertTrue(app.wait(for: .runningForeground, timeout: 10))
        dump(screenName: "appointment-input-top")
        app.swipeUp()
        dump(screenName: "appointment-input-bottom")
    }

    private func dump(screenName: String) {
        let screenshot = XCTAttachment(screenshot: app.screenshot())
        screenshot.name = "canvas-\(screenName).png"
        screenshot.lifetime = .keepAlways
        add(screenshot)

        let appFrame = app.frame
        let elements = app.descendants(matching: .any).allElementsBoundByIndex.compactMap { element -> [String: Any]? in
            let identifier = element.identifier
            let frame = element.frame
            guard !identifier.isEmpty,
                  frame != .zero,
                  appFrame.contains(frame)
            else {
                return nil
            }

            return [
                "id": identifier,
                "type": String(describing: element.elementType),
                "frame": [
                    "x": frame.origin.x,
                    "y": frame.origin.y,
                    "w": frame.size.width,
                    "h": frame.size.height
                ],
                "label": element.label
            ]
        }

        let payload: [String: Any] = [
            "screen": screenName,
            "appFrame": ["w": appFrame.size.width, "h": appFrame.size.height],
            "elements": elements
        ]
        guard JSONSerialization.isValidJSONObject(payload),
              let jsonData = try? JSONSerialization.data(withJSONObject: payload, options: [.prettyPrinted, .sortedKeys])
        else {
            XCTFail("Atlas JSON 생성에 실패했습니다: \(screenName)")
            return
        }

        let json = XCTAttachment(data: jsonData, uniformTypeIdentifier: "public.json")
        json.name = "frames-\(screenName).json"
        json.lifetime = .keepAlways
        add(json)
    }
}

