  /* 224px는 사라진 왼쪽 사이드바의 폭이었다. 맞출 대상이 없어 auto로 둔다. */
  grid-template-columns: auto 1fr auto;
  align-items: center;
  height: 72px;
  padding: 0 20px;
  background: rgba(255, 255, 252, 0.96);
